; jump.asm -- chapter 47: a runner that jumps
; generated by gen47.py
        INCLUDE "msx.inc"
        OUTPUT "jump.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
stat    EQU VARS                ; the status isr read
ticks   EQU VARS + 1            ; frames counted by isr, two bytes
held    EQU VARS + 3            ; the keys of the frame: a 0 for each held
dleft   EQU VARS + 4            ; the frames left of the demo's pair
dnext   EQU VARS + 5            ; the demo's next pair, two bytes
copy    EQU VARS + $20          ; the sprites' attributes: Y, X, pattern, colour
SAT     EQU $1B00               ; the sprites' attributes in the VRAM
SPAT    EQU $3800               ; and their patterns
rx      EQU VARS + 8            ; the runner's x
ry      EQU VARS + 9            ; its top line: y's whole lines
yfrac   EQU VARS + 10           ; and y's 256ths
vy      EQU VARS + 11           ; the speed, 8.8, down positive: two bytes
landed  EQU VARS + 13           ; 1 on a ledge, 0 in the air
JUMP    EQU $0380             ; the speed up at a jump's start: 3.5 lines a frame
GRAVITY EQU $0028             ; added every frame: 40/256 of a line
MAXFALL EQU $0400             ; down at most 4 lines a frame
RUN     EQU 2                   ; pixels a frame, left or right
X_LAST  EQU 240                 ; the runner's x from 0 to X_LAST
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; A runner on ledges of bricks, a sprite, running and jumping as the demo's
; keys say: y and the speed in 8.8, gravity every frame, a landing on the
; top of a ledge's cell; and a dot at its feet every frame, with chapter 25's
; plot, on a screen whose names run 0 to 255 in each third.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $FF          ; colours  $2000, a set for each third
        VDP_REG 4, $03          ; shapes   $0000, a set for each third
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $01          ; the border
        VRAM_WRITE SAT          ; no sprites yet
        ld a, $D0
        out (VDP_DATA), a
        ld hl, VARS             ; the variables' page, all 0
        ld de, VARS + 1
        ld bc, 255
        ld (hl), 0
        ldir
        ld a, 1
        ld (dleft), a           ; the demo's first pair at the first frame
        ld hl, demo
        ld (dnext), hl
        ld hl, first            ; the sprite's attributes at the start
        ld de, copy
        ld bc, 5
        ldir
        ld a, 16
        ld (rx), a
        ld a, 168
        ld (ry), a
        ld a, 1
        ld (landed), a          ; on the floor
        VRAM_WRITE $0000        ; the patterns, cell by cell: a ledge's brick
        ld de, ledges           ; or nothing
        ld hl, brick
        call cells
        VRAM_WRITE $2000        ; the colours: the brick's, or the sky's
        ld de, ledges
        ld hl, bcols
        call cells
        VRAM_WRITE $1800        ; the names: 0 to 255 in each third
        ld b, 3
.third: xor a
.name:  out (VDP_DATA), a
        inc a
        jr nz, .name
        djnz .third
        VRAM_WRITE SPAT         ; the runner's patterns
        ld hl, sprite
        ld bc, 32 << 8 | VDP_DATA
        otir
        jp on

; cells: DE = the map, HL = 8 bytes for a ledge's cell, 8 more for the sky's
;        -> 768 cells' bytes to the VRAM, with the display off
cells:  ld bc, 768
.cell:  push bc
        push hl
        ld a, (de)
        or a
        jr nz, .put             ; a ledge: the first 8
        ld bc, 8
        add hl, bc              ; the sky: the next 8
.put:   ld bc, 8 << 8 | VDP_DATA
        otir
        pop hl
        pop bc
        inc de
        dec bc
        ld a, b
        or c
        jr nz, .cell
        ret
on:     ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        in a, (VDP_CTRL)        ; no signal left over
        VDP_REG 1, $E2          ; display on, the frame's signal
main:   ei
frame:  halt                    ; isr: the status kept, the frame counted
woke:   call sends              ; 18  what the beam must not catch
sent:   call run                ; 18  the frame's work
ran:    jr frame                ; 13

; isr: every frame. The status kept in stat, the signal let down; the frame
; counted. Keeps AF, HL
isr:    push af                 ; 12
        in a, (VDP_CTRL)        ; 12  the status: F, 5S, C, a sprite's number
        ld (stat), a            ; 14
        push hl                 ; 12
        ld hl, (ticks)          ; 17
        inc hl                  ;  7
        ld (ticks), hl          ; 17
        pop hl                  ; 11
        pop af                  ; 11
isrend: ei                      ;  5
        ret                     ; 11

; pad: the demo's keys for this frame -> A and held, as chapter 43's input
;      gives them, a 0 for each key held. The demo is pairs of bytes, frames
;      and keys, with a 0 at its end, after which it starts again. Uses A, HL
pad:    ld hl, dleft            ; 11
        dec (hl)                ; 12  a frame fewer of these keys
        jr nz, .same            ; 13, or 8
        ld hl, (dnext)          ; 17  none left: the next pair
        ld a, (hl)              ;  8  its frames
        or a                    ;  5
        jr nz, .pair            ; 13, or 8
        ld hl, demo             ; 11  the end: the first pair again
        ld a, (hl)              ;  8
.pair:  ld (dleft), a           ; 14
        inc hl                  ;  7
        ld a, (hl)              ;  8  its keys
        ld (held), a            ; 14
        inc hl                  ;  7
        ld (dnext), hl          ; 17
        ret                     ; 11
.same:  ld a, (held)            ; 14  the same keys as before
        ret                     ; 11

; sends: straight after HALT, before the paper: the runner's attributes, and
;        a dot at its feet, both for the place the frame before worked out.
;        Uses A, BC, DE, HL
sends:  VRAM_WRITE SAT          ; 40
        ld hl, copy             ; 11
        ld bc, 5 << 8 | VDP_DATA ; 11  the runner and the end
        otir                    ; 23 a byte, 18 the last

; trail: a dot between the runner's feet, on their last line, at x + 7,
;        y + 15, with chapter 25's plot. Uses A, BC, DE, HL
trail:  ld a, (rx)              ; 14
        add a, 7                ;  8
        ld b, a                 ;  5  B: x
        ld a, (ry)              ; 14
        add a, 15               ;  8
        ld c, a                 ;  5  C: y
        jp plot                 ; 11  whose RET is sends'

; run: the frame's work: the demo's keys, a walk, a fall or a jump, and the
;      runner's attributes for the next frame. Uses every register
run:    call pad                ; 18  A: the keys
        call walk               ; 18
        ld a, (held)            ; 14
        call fall               ; 18
place:  ld a, (ry)              ; 14  the copy: Y, a line above the top
        dec a                   ;  5
        ld (copy), a            ; 14
        ld a, (rx)              ; 14  and X
        ld (copy + 1), a        ; 14
        ret                     ; 11

; walk: A = the keys -> the runner two pixels left for LEFT, right for
;       RIGHT, x from 0 to X_LAST. Uses A, B, HL
walk:   ld b, a                 ;  5
        ld hl, rx               ; 11
        bit 2, b                ; 10  LEFT?
        jr nz, .right           ; 13, or 8
        ld a, (hl)              ;  8
        or a                    ;  5
        jr z, .right            ; 13, or 8  at the left edge
        sub RUN                 ;  8
        ld (hl), a              ;  8
.right: bit 3, b                ; 10  RIGHT?
        ret nz                  ; 12, or 6
        ld a, (hl)              ;  8
        cp X_LAST               ;  8
        ret nc                  ; 12, or 6  at the right edge
        add a, RUN              ;  8
        ld (hl), a              ;  8
        ret                     ; 11

; fall: A = the keys -> SPACE on a ledge starts a jump, the speed JUMP up;
;       gravity adds GRAVITY to the speed, down at most MAXFALL, and the
;       speed is added to y. Both are 8.8: the high byte whole lines, the
;       low byte 256ths of a line. Going down, feet that reach the top of a
;       ledge's cell stop there. Uses A, BC, DE, HL
fall:   ld hl, (vy)             ; 17  the speed, down positive
        bit 4, a                ; 10  SPACE?
        jr nz, .grav            ; 13, or 8
        ld a, (landed)          ; 14
        or a                    ;  5
        jr z, .grav             ; 13, or 8  in the air: no jump
        ld hl, -JUMP            ; 11  a jump
.grav:  ld de, GRAVITY          ; 11
        add hl, de              ; 12  gravity
        bit 7, h                ; 10
        jr nz, .fast            ; 13, or 8  going up
        ld a, h                 ;  5
        cp high MAXFALL         ;  8
        jr c, .fast             ; 13, or 8
        ld hl, MAXFALL          ; 11  no faster
.fast:  ld (vy), hl             ; 17
        ex de, hl               ;  5  DE: the speed
        ld a, (ry)              ; 14  y's whole lines
        ld h, a                 ;  5
        ld a, (yfrac)           ; 14  and its 256ths
        ld l, a                 ;  5
        add hl, de              ; 12  HL: the new y
        bit 7, d                ; 10
        jr nz, .air             ; 13, or 8  going up: in the air
        ld a, h                 ;  5
        add a, 16               ;  8  the line under the new feet
        and $F8                 ;  8  the top line of its cell
        ld c, a                 ;  5  C
        ld a, (ry)              ; 14
        add a, 16               ;  8  the line under the feet before
        cp c                    ;  5
        jr z, .look             ; 13, or 8  on that top already
        jr nc, .air             ; 13, or 8  below it: not reached
.look:  call under              ; 18  a ledge in that row?
        jr z, .air              ; 13, or 8  none: on in the air
        ld a, c                 ;  5
        sub 16                  ;  8
        ld (ry), a              ; 14  the feet on the ledge's top
        xor a                   ;  5
        ld (yfrac), a           ; 14
        ld h, a                 ;  5
        ld l, a                 ;  5
        ld (vy), hl             ; 17  still
        inc a                   ;  5
        ld (landed), a          ; 14  on a ledge
        ret                     ; 11
.air:   ld a, h                 ;  5
        ld (ry), a              ; 14  the new y
        ld a, l                 ;  5
        ld (yfrac), a           ; 14
        xor a                   ;  5
        ld (landed), a          ; 14  in the air
        ret                     ; 11

; under: C = the top line of a row of cells -> NZ if a ledge's cell is in
;        that row under the runner's 16 pixels: two cells, or three when x
;        is not a multiple of 8; ledges, the cartridge's map of the cells,
;        holds 1 for a ledge's. Uses A, B, DE
under:  ld a, c                 ;  5  the line, 8 times the row
        rlca                    ;  5
        rlca                    ;  5  the row times 32, its high bits low
        ld b, a                 ;  5
        and $E0                 ;  8  the low byte
        ld e, a                 ;  5
        ld a, b                 ;  5
        and 3                   ;  8
        add a, high ledges      ;  8  and the high
        ld d, a                 ;  5  DE: the row's first cell
        ld a, (rx)              ; 14  x
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and 31                  ;  8  its column
        or e                    ;  5
        ld e, a                 ;  5  DE: the cell under its left
        ld a, (de)              ;  8
        or a                    ;  5
        ret nz                  ; 12, or 6  a ledge
        inc e                   ;  5
        ld a, (de)              ;  8  the next cell
        or a                    ;  5
        ret nz                  ; 12, or 6
        ld a, (rx)              ; 14
        and 7                   ;  8
        ret z                   ; 12, or 6  two cells only: none
        inc e                   ;  5
        ld a, (de)              ;  8  the third
        or a                    ;  5
        ret                     ; 11


; vaddr: B = x, C = y -> HL = the address of the byte that holds pixel (x, y),
; in the patterns of a Graphic II screen whose names run 0 to 255 in each
; third (chapter 22). Uses A.
vaddr:  ld a, c                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8: y / 8, the row of characters
        ld h, a                 ;  5
        ld a, b                 ;  5
        and $F8                 ;  8: the column of characters, x 8
        ld l, a                 ;  5
        ld a, c                 ;  5
        and 7                   ;  8: the line in the cell
        or l                    ;  5
        ld l, a                 ;  5
        ret                     ; 11

; plot: B = x, C = y: pixel (x, y) set, the other seven of its byte kept:
; the byte read, changed and written back. Uses A, DE, HL.
plot:   call vaddr              ; 18  HL: the byte
        ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12  the read address
        ld a, h                 ;  5
        out (VDP_CTRL), a       ; 12  ... and the VDP reads the byte ahead
        ld d, high masks        ;  8  while it reads, the pixel's mask
        ld a, b                 ;  5
        and 7                   ;  8
        ld e, a                 ;  5
        ld a, (de)              ;  8
        ld e, a                 ;  5  E: $80 >> (x AND 7)
        in a, (VDP_DATA)        ; 12  the byte
        or e                    ;  5  and the pixel
        ld e, a                 ;  5
        ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12  the write address
        ld a, h                 ;  5
        or $40                  ;  8
        out (VDP_CTRL), a       ; 12
        ld a, e                 ;  5
        out (VDP_DATA), a       ; 12  the byte, with the pixel
        ret                     ; 11
brick:                          ; a ledge's cell: chapter 39's brick; the sky's
        db $FF, $80, $80, $80, $FF, $08, $08, $08
        db $00, $00, $00, $00, $00, $00, $00, $00
bcols:                          ; their colours
        db $16, $16, $16, $16, $16, $16, $16, $16
        db $F1, $F1, $F1, $F1, $F1, $F1, $F1, $F1
first:                          ; the runner's attributes at the start, and the end
        db $A7, $10, $00, $07, $D0
sprite:                         ; the runner, 16 x 16 (chapter 26)
        db $03, $07, $05, $07, $03, $01, $1F, $2F
        db $27, $07, $06, $06, $06, $06, $0E, $0E
        db $C0, $E0, $A0, $E0, $C0, $80, $F8, $F4
        db $E4, $E0, $60, $60, $60, $60, $70, $70
; the demo, a lap of the ledges: pairs of frames and keys, a 0 for each key held,
; and a 0 at the end
demo:   db 10, %11110111        ; RIGHT
        db 1, %11100111         ; RIGHT SPACE
        db 35, %11110111        ; RIGHT
        db 1, %11100111         ; RIGHT SPACE
        db 35, %11110111        ; RIGHT
        db 1, %11100111         ; RIGHT SPACE
        db 14, %11110111        ; RIGHT
        db 21, %11111111        ; none
        db 1, %11101011         ; LEFT SPACE
        db 35, %11111011        ; LEFT
        db 1, %11101011         ; LEFT SPACE
        db 60, %11111011        ; LEFT
        db 38, %11111111        ; none
        db 0                    ; the end: the first pair again

        ALIGN 256
masks:  db $80, $40, $20, $10, $08, $04, $02, $01   ; pixel n of a byte: bit 7 - n
        ALIGN 256
ledges:                         ; the cells: 1 for a ledge's, 24 rows of 32
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $01, $01, $01, $01, $01, $01, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01
        db $01, $01, $01, $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $01, $01, $01, $01, $01
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $01, $01, $01, $01, $01, $01, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $01, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
